CREATE TYPE "AuthProvider" AS ENUM ('GOOGLE');
CREATE TYPE "UserRole" AS ENUM ('USER','ADMIN');
CREATE TYPE "UserStatus" AS ENUM ('ACTIVE','SUSPENDED','DISABLED','DELETED');
CREATE TYPE "SecuritySeverity" AS ENUM ('INFO','LOW','MEDIUM','HIGH','CRITICAL');
CREATE TABLE "users" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"google_sub" TEXT NOT NULL UNIQUE,"email" TEXT NOT NULL,"email_verified" BOOLEAN NOT NULL,"name" TEXT,"avatar_url" TEXT,"provider" "AuthProvider" NOT NULL DEFAULT 'GOOGLE',"role" "UserRole" NOT NULL DEFAULT 'USER',"status" "UserStatus" NOT NULL DEFAULT 'ACTIVE',"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),"last_login_at" TIMESTAMPTZ,"last_activity_at" TIMESTAMPTZ,"deleted_at" TIMESTAMPTZ);
CREATE UNIQUE INDEX "users_provider_google_sub_key" ON "users"("provider","google_sub"); CREATE INDEX "users_email_idx" ON "users"("email"); CREATE INDEX "users_status_idx" ON "users"("status");
CREATE TABLE "profiles" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"user_id" UUID NOT NULL UNIQUE REFERENCES "users"("id") ON DELETE CASCADE,"display_name" TEXT,"avatar_url" TEXT,"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE "devices" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"user_id" UUID NOT NULL REFERENCES "users"("id") ON DELETE CASCADE,"fingerprint_hash" TEXT NOT NULL,"user_agent" TEXT,"ip_address" TEXT,"first_seen_at" TIMESTAMPTZ NOT NULL DEFAULT now(),"last_seen_at" TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE("user_id","fingerprint_hash"));
CREATE TABLE "sessions" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"user_id" UUID NOT NULL REFERENCES "users"("id") ON DELETE CASCADE,"token_hash" TEXT NOT NULL UNIQUE,"device_id" UUID REFERENCES "devices"("id") ON DELETE SET NULL,"ip_address" TEXT,"user_agent" TEXT,"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),"last_seen_at" TIMESTAMPTZ NOT NULL DEFAULT now(),"expires_at" TIMESTAMPTZ NOT NULL,"revoked_at" TIMESTAMPTZ,"revoke_reason" TEXT); CREATE INDEX "sessions_user_active_idx" ON "sessions"("user_id","revoked_at","expires_at");
CREATE TABLE "login_history" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"user_id" UUID REFERENCES "users"("id") ON DELETE SET NULL,"provider" "AuthProvider" NOT NULL DEFAULT 'GOOGLE',"success" BOOLEAN NOT NULL,"failure_reason" TEXT,"ip_address" TEXT,"user_agent" TEXT,"metadata" JSONB,"created_at" TIMESTAMPTZ NOT NULL DEFAULT now()); CREATE INDEX "login_history_user_created_idx" ON "login_history"("user_id","created_at");
CREATE TABLE "security_events" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"user_id" UUID REFERENCES "users"("id") ON DELETE SET NULL,"event_type" TEXT NOT NULL,"severity" "SecuritySeverity" NOT NULL,"metadata" JSONB,"created_at" TIMESTAMPTZ NOT NULL DEFAULT now()); CREATE INDEX "security_events_lookup_idx" ON "security_events"("user_id","event_type","created_at");
CREATE TABLE "audit_logs" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"actor_user_id" UUID REFERENCES "users"("id") ON DELETE SET NULL,"action" TEXT NOT NULL,"resource_type" TEXT NOT NULL,"resource_id" TEXT,"metadata" JSONB,"created_at" TIMESTAMPTZ NOT NULL DEFAULT now()); CREATE INDEX "audit_logs_actor_action_idx" ON "audit_logs"("actor_user_id","action","created_at");
